52.	Service Details
53.	Service Details
--------------------------------------------------------------*/
/*
  font-family: 'Teko', sans-serif;
  font-family: 'Barlow', sans-serif;
  font-family: 'Rubik', sans-serif;
*/
/***

====================================================================
2.	Reset
====================================================================

 ***/
* {
  margin: 0px;
  padding: 0px;
  border: none;
  outline: none;
  font-size: 100%;
  line-height: inherit;
}

/***



 ***/

:root {
  --thm-font: "Teko", sans-serif;
  --thm-b-font: "Rubik", sans-serif;
  --thm-base: #0051c2;
  --thm-base-rgb: #0051c2;;
  --thm-black: #333333;
  --thm-text: #000000;
}

.container {
  padding-left: 15px;
  padding-right: 15px;
}

.row {
  --bs-gutter-x: 30px;
  --bs-gutter-y: 0px;
}



body {
  font-size: 16px;
  font-family: var(--thm-b-font);
  color: var(--thm-text);
  line-height: 2.125em;
  font-weight: 400;
  background: #fffdfd;
  -webkit-font-smoothing: antialiased;
  -moz-font-smoothing: antialiased;
  top: 0 !important;
}

a {
  text-decoration: none;
  cursor: pointer;
  color: var(--thm-base);
}


.owl-nav {
  position: absolute;
  top: 50%;
  width: 100%;
  display: flex;
  justify-content: space-between;
  transform: translateY(-50%);
}

.owl-nav .owl-prev, .owl-nav .owl-next {
  background-color: #0051c2;;
  color: #fff;
  padding: 10px;
  cursor: pointer;
  border-radius: 50%;
  font-size: 20px;
}

.owl-nav .owl-prev {
  margin-left: 10px;
}

.owl-nav .owl-next {
  margin-right: 10px;
}


.theme_color {
  color: var(--thm-base);
}

a:hover,
a:focus,
a:visited,
a:active,
button:active {
  text-decoration: none;
  outline: none;
}

h1,
h2,
h3,
h4,
h5,
h6 {
  position: relative;
  font-weight: 400;
  margin: 0px 0px 20px;
  background: none;
  line-height: 1.25em;
  font-family: var(--thm-font);
  color: var(--thm-black);
}

h1 {
  font-size: 140px;
}

h2 {
  font-size: 70px;
}

h3 {
  font-size: 60px;
}

h4 {
  font-size: 40px;
}

h5 {
  font-size: 30px;
}

h6 {
  font-size: 26px;
}

input,
select,
button {
  font-family: var(--thm-font);
}

textarea {
  overflow: hidden;
  resize: none;
}

button {
  outline: none !important;
  cursor: pointer;
}

p {
  line-height: 2.125em;
  margin: 0 0 20px;
}

.text {
  line-height: -2.125em;
  margin: 0 0;
}

::-webkit-input-placeholder {
  color: inherit;
}

::-moz-input-placeholder {
  color: inherit;
}

::-ms-input-placeholder {
  color: inherit;
}

.page-wrapper {
  position: relative;
  margin: 0 auto;
  width: 100%;
  min-width: 300px;
  z-index: 9;
  overflow: hidden;
}

.page-wrapper__dark {
  background-color: #ffffff;
  background-image: url(../images/background/home-portfolio-bg-1-1.html);
}

.page-wrapper__gradient {
  background:#100089 ;
  background: linear-gradient(to right #0051c2);
}

body.boxed-wrapper {
  background-color: #00a2ff;
}

body.boxed-wrapper {
  background-color: #00a2ff;
}

.page-wrapper__dark.boxed-wrapper {
  background-color: #00a2ff;
}

@media (max-width: 1440px) {
  .page-wrapper.boxed-wrapper {
    max-width: 90%;
  }
}

@media (max-width: 768px) {
  .page-wrapper.boxed-wrapper {
    max-width: 95%;
  }
}

.auto-container {
  position: static;
  max-width:1292px;
  padding: 0px 15px;
  margin: 0 auto;
}

.whatsapp-icon {
  text-align: right;
  font-size: 1.5rem;
  font-weight: bold;
  margin-top: 10px;
}


ul,
li {
  list-style: none;
  padding: 0px;
  margin: 0px;
}

figure {
  margin-bottom: 0;
}

.theme-btn {
  display: inline-block;
  -webkit-transition: all 0.3s ease;
  transition: all 0.3s ease;
}

.theme-btn i {
  position: relative;
  display: inline-block;
  font-size: 14px;
  margin-left: 3px;
}

.centered {
  text-align: center !important;
}

/*Btn Style One*/
.btn-style-one {
  position: relative;
  display: inline-block;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: linear-gradient(to right, #0e31cf, #4d99e6, #240cd4);
  color: var(--thm-black);
  border-radius: 5px;
  overflow: hidden;
  font-family: var(--thm-font);
  transition: all 0.3s ease;
  -moz-transition: all 0.3s ease;
  -webkit-transition: all 0.3s ease;
  -ms-transition: all 0.3s ease;
  -o-transition: all 0.3s ease;
}

.btn-style-one .btn-title {
  position: relative;
  display: block;
  font-size: 18px;
  line-height: 30px;
  font-weight: 400;
  letter-spacing: 0.1em;
  padding: 19px 50px 16px;
  z-index: 1;
}

.btn-style-one:hover {
  background: linear-gradient(to right, #0e31cf, #4d99e6, #240cd4);
  color: #ffffff;
}

.btn-style-one .btn-curve {
  position: absolute;
  right: -15px;
  top: 0;
  width: 26px;
  height: 100%;
  background: var(--thm-black);
  opacity: 0.2;
  z-index: 0;
  -webkit-transform: skewX(-22deg);
  transform: skewX(-22deg);
  transition: all 0.5s ease;
  -moz-transition: all 0.5s ease;
  -webkit-transition: all 0.5s ease;
  -ms-transition: all 0.5s ease;
  -o-transition: all 0.5s ease;
}

.btn-style-one:hover .btn-curve {
  opacity: 1;
  right: 0;
  width: 100%;
  -webkit-transform: skewX(0deg);
  transform: skewX(0deg);
}

/*Btn Style Two*/
.btn-style-two {
  position: relative;
  display: inline-block;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: linear-gradient(to right, #0e31cf, #4d99e6, #240cd4);
  color: var(--thm-black);
  border-radius: 5px;
  overflow: hidden;
  font-family: var(--thm-font);
  transition: all 0.3s ease;
  -moz-transition: all 0.3s ease;
  -webkit-transition: all 0.3s ease;
  -ms-transition: all 0.3s ease;
  -o-transition: all 0.3s ease;
}

.btn-style-two .btn-title {
  position: relative;
  display: block;
  font-size: 18px;
  line-height: 30px;
  font-weight: 400;
  padding: 19px 50px 16px;
  z-index: 1;
  letter-spacing: 0.1em;
  -webkit-transition: 0.5s;
  transition: 0.5s;
}

.btn-style-two:hover {
  background: linear-gradient(to right, #0e31cf, #4d99e6, #240cd4);
  color: #ffffff;
}

.btn-style-two .btn-curve {
  position: absolute;
  right: -15px;
  top: 0;
  width: 26px;
  height: 100%;
  background: var(--thm-black);
  opacity: 0.2;
  z-index: 0;
  -webkit-transform: skewX(-22deg);
  transform: skewX(-22deg);
  transition: all 0.5s ease;
  -moz-transition: all 0.5s ease;
  -webkit-transition: all 0.5s ease;
  -ms-transition: all 0.5s ease;
  -o-transition: all 0.5s ease;
}

.btn-style-two:hover .btn-curve {
  opacity: 1;
  right: 0;
  width: 100%;
  -webkit-transform: skewX(0deg);
  transform: skewX(0deg);
}

.btn-style-three {
  background: linear-gradient(to right, #3c0ad4, #6092f5, #280cdf);
  color: #fff;
  font-size: 16px;
  font-weight: bold;
  padding: 22.5px 40px;
  font-family: var(--thm-font);
  display: -webkit-inline-box;
  display: -ms-inline-flexbox;
  display: inline-flex;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  line-height: 1;
}

.btn-style-three:hover {
  background-color: var(--thm-black);
  color: #fff;
}

.pull-right {
  float: right;
}

.pull-left {
  float: left;
}

.preloader {
  position: fixed;
  left: 0px;
  top: 0px;
  width: 100%;
  height: 100%;
  z-index: 999999;
  background-color: white;
  background-color: #1c1e22;
}

.preloader__gradient {
  background: #432ff6;
  background: linear-gradient(100deg, #432ff6 0%, #3122be 100%);
}

@keyframes fadeInOut {
  0%, 100% {
    opacity: 0;
  }
  50% {
    opacity: 1;
  }
}

@keyframes rotateMe {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

.preloader .icon {
  position: fixed;
  left: 0px;
  top: 0px;
  width: 100%;
  height: 100%;
  z-index: 5;
  background-color: rgba(0, 0, 0, 0);
  background-position: center center;
  background-repeat: no-repeat;
  background-image: url(../img/logo/logo_blanc.png);

  /* Rotate animation */
  animation:  infinite linear, fadeInOut 2s infinite ease-in-out;

  /* Transition for smooth fading */
  transition: opacity 200ms ease-in-out;
}


.preloader__gradient .icon {
  background-image: url(../images/update-26-02-2021/preloader-white.html);
}

.page-loaded .preloader .icon {
  opacity: 0;
}

img {
  display: inline-block;
  max-width: 100%;
  height: auto;
}

.dropdown-toggle::after {
  display: none;
}

.fa {
  line-height: inherit;
}

/***

====================================================================
4.	Scroll To Top style
====================================================================

***/
.scroll-to-top {
  position: fixed;
  right: 20px;
  bottom: 20px;
  width: 44px;
  height: 44px;
  color: var(--thm-black);
  font-size: 14px;
  line-height: 44px;
  border-radius: 50%;
  text-align: center;
  z-index: 100;
  cursor: pointer;
  background: linear-gradient(to right, #024cf8, #63a1f7, #140dd6);
  display: none;
  -webkit-transition: all 300ms ease;
  transition: all 300ms ease;
}

.scroll-to-top:hover {
  background: var(--thm-black);
  color: #ffffff;
}




.main {
  display: flex;
  align-items: flex-end;

  position: relative;
  /* This ensures all bars start growing from the bottom */
}

.bar {
  background-color: #1602f9e0;
  width: 36px;
  margin-left: 20px;
  height: 0;
  /* Start with 0 height */
  animation: growHeight 2s forwards;
  /* Apply animation to grow height */
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  font-size: 20px;
  padding-left: 5px;
  padding-right: 5px;
  border-top-left-radius: 12px;
}

.testt {
  display: flex;
  align-content: center;
  justify-content: center;
  /* background-color: #112350; */
  width: fit-content;
}

#thearoow{
  position: absolute;
  top: -90px;
  left: 67px;
  opacity: 0;
  height: fit-content;
  transform: rotate(23deg);
  /* width: 261px !important; */
  animation: fade 2s forwards;
}

.firstbar {
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  /* Ensure text is at the bottom */
}

.firstbar span {
  margin-top: 5px;
  font-size: 16px;
}

@keyframes fade {
  0% {
      opacity: 0;
  }

  100% {
      opacity: 1;
  }
}

@keyframes growHeight {
  0% {
      height: 0;
  }

  100% {
      height: var(--target-height);
  }
}




/***



====================================================================
5.	Main Header style / Header Style One
====================================================================

***/
.main-header {
  position: absolute;
  left: 0;
  top: 0;
  display: block;
  width: 100%;
  z-index: 9999;
  background: none;
}

/*=== Header Main Box ===*/
.main-header .header-upper {
  position: fixed;
  display: block;
  left: 0;
  top: 0;
  width: 100%;
  background: none;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 1;
  -webkit-transition: all 300ms ease;
  transition: all 300ms ease;
}




.boxed-wrapper .main-header .header-upper {
  max-width: 1410px;
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
}

.fixed-header .header-upper {
  background: #ffffff;
  -ms-box-shadow: 0 10px 30px 0px rgba(255, 249, 249, 0.08);
  -o-box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
  -webkit-box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
  box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
}

.header-style-two.fixed-header .header-upper {
  background: var(--thm-black);
  -ms-box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
  -o-box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
  -webkit-box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
  box-shadow: 0 10px 30px 0px rgba(255, 255, 255, 0.08);
}

.main-header .header-upper .inner-container {
  position: relative;
  display: block;
  padding: 0px 60px;
}


.main-header .header-upper .logo-box {
  position: relative;
  float: left;
  padding: 40px 0px;
  margin-right: 50px;
  z-index: 7;
}

.main-header .header-upper .logo-box .logo {
  position: relative;
  display: block;
}

.main-header .header-upper .logo-box .logo img {
  position: relative;
  display: inline-block;
  max-width: 100%;
  max-height: 50px;
  z-index: 1;
}

.main-header .other-links {
  position: relative;
  float: right;
  z-index: 7;
}

.main-header .other-links .link-box {
  position: relative;
  float: left;
  padding: 34px 0px;
}

.main-header .other-links .link-box .link {
  position: relative;
  display: block;
  padding-top: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding-left: 60px;
  color: #ffffff;
}

.header-style-two.fixed-header .other-links .link-box .link {
  color: #ffffff;
}

.main-header .other-links .link-box .link .icon {
  position: absolute;
  left: 0;
  top: 0;
  width: 44px;
  height: 42px;
  background: url(../img/icons/chat-icon.png) left center no-repeat;
}

.main-header .other-links .link-box .sub-text {
  position: relative;
  display: block;
  font-size: 14px;
  font-weight: 500;
  line-height: 18px;
  font-family: var(--thm-font);
  letter-spacing: 0.03em;
}

.main-header .other-links .link-box .number {
  position: relative;
  display: block;
  letter-spacing: 0.03em;
  font-size: 20px;
  font-weight: 400;
  line-height: 24px;
  font-family: var(--thm-font);
}

.main-header .other-links .link-box .number:hover {
  text-decoration: underline;
}

.main-header .other-links .call-us {
  position: relative;
}

.main-header .other-links .search-btn {
  position: relative;
  float: left;
  padding: 40px 0px;
  padding-right: 50px;
  margin-right: 50px;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
}

.main-header .other-links .search-btn button {
  position: relative;
  display: block;
  padding: 0;
  margin: 0;
  background: none;
  line-height: 32px;
  color: #0202fd;
  cursor: pointer;
}

.main-header .other-links .search-btn button span {
  vertical-align: middle;
}

.main-header .other-links .social-links-nav {
  position: relative;
  float: left;
  padding: 40px 0px;
  padding-right: 50px;
  margin-right: 50px;
  border-right: 1px solid #0202fd;
  display: flex;
  align-items: center;
  gap: 15px;
}

.main-header .other-links .social-links-nav a {
  position: relative;
  display: inline-block;
  font-size: 20px;
  color:#0202fd !important;
  transition: all 300ms ease;
  line-height: 1;
}

.main-header .other-links .social-links-nav a i {
  color: #0202fd !important;
}

.main-header .other-links .social-links-nav a:hover {
  color: var(--thm-base) !important;
  transform: translateY(-2px);
}

.main-header .other-links .social-links-nav a:hover i {
  color: var(--thm-base) !important;
}

.main-header .nav-outer {
  position: absolute;
  left: 0;
  top: 0;
  float: left;
  text-align: left;
  width: 100%;
  z-index: 5;
  padding-left: 200px;
}

.main-header .nav-outer .main-menu {
  position: relative;
  display: inline-block;
  vertical-align: middle;
}

@media (min-width: 992px) {
  .boxed-wrapper .main-header .nav-outer .main-menu {
    margin-right: 70px;
  }
}

.main-menu .navbar-collapse {
  padding: 0px;
  display: block !important;
}

.main-menu .navigation {
  position: relative;
  display: block;
  width: 100%;
  margin: 0px;
  font-family: var(--thm-font);
}

.main-menu .navigation>li {
  position: relative;
  float: left;
  padding: 31px 0px;
  margin-right: 40px;
  -webkit-transition: all 300ms ease;
  transition: all 300ms ease;
}

.main-menu .navigation>li:last-child {
  margin-right: 0px;
}

.main-menu .navigation>li:last-child:after {
  display: none;
}

.main-menu .navigation>li>a {
  position: relative;
  display: block;
  text-align: center;
  font-size: 20px;
  line-height: 30px;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: #ffffff;
  padding: 12px 0px;
  opacity: 1;
  -webkit-transition: all 300ms ease;
  transition: all 300ms ease;
}

.main-menu .navigation li>a {
  display: -webkit-box !important;
  display: -ms-flexbox !important;
  display: flex !important;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  -webkit-box-pack: justify;
  -ms-flex-pack: justify;
  justify-content: space-between;
}

.main-menu .navigation li>a>span {
  background: linear-gradient(to right, #1915df, #440de9, #4c9cf8);
  color: #fff;
  font-size: 13px;
  text-transform: uppercase;
  border-radius: 5px;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: center;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  text-align: center;
  width: 40px;
  top: -3px;
  position: relative;
}

.main-menu .navigation>li:hover>a,
.main-menu .navigation>li.current>a {
  color: #0202fd;
}

.header-style-two .main-menu .navigation>li>a,
.header-style-two .main-menu .navigation>li:hover>a {
  color: var(--thm-black);
