/* styles.css */

.popup {
  display: none;
  position: fixed;
  z-index: 1000;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  justify-content: center;
  align-items: center;
  opacity: 0;
  transition: opacity 0.5s ease;
}

/* Popup content */
.popup-content {
  background-color: #fff;
  padding: 20px;
  border-radius: 5px;
  width: 500px;
  text-align: center;
  transform: scale(0.7);
  transition: transform 0.5s ease;
  position: relative;
}

/* Close button icon */
.close-btn {
  position: absolute;
  top: 10px;
  right: 15px;
  font-size: 28px;
  cursor: pointer;
  color: #fff;
  background-color: #e53935; /* Rouge vif */
  padding: 8px;
  border-radius: 50%;
  z-index: 1000;
  transition: all 0.3s ease;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.close-btn:hover {
  background-color: #b71c1c; /* Rouge foncé au survol */
  color: #fff;
}


/* Styled close button */
.styled-button {
  background: linear-gradient(to right, #1915df, #440de9, #4c9cf8); /* Custom color */
  color: #fff;
  border: none;
  border-radius: 25px; /* Rounded corners */
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
  transition: background-color 0.3s ease, transform 0.2s ease;
  margin-top: 20px;
}

/* Hover effect for the button */
.styled-button:hover {
  background-color: #254dd1; /* Slightly darker shade on hover */
  transform: scale(1.05); /* Slightly enlarge on hover */
}

/* Show the popup with fade-in and scale-up effect */
.popup.show {
  display: flex;
  opacity: 1;
}

.popup-content.show {
  transform: scale(1);
}




