/*--------------------------------------------------------------
# Side Scroller Dots
--------------------------------------------------------------*/
.side-scroller-dots {
  position: fixed;
  top: 50%;
  right: 100px;
  -webkit-transform: translateY(-50%);
  transform: translateY(-50%);
  z-index: 99;
}

.side-scroller-dots ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.side-scroller-dots ul li+li {
  margin-top: 10px;
}

.side-scroller-dots ul li a span {
  position: relative;
  display: block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #191f37;
  -webkit-transition: all .4s ease;
  transition: all .4s ease;
  z-index: 1;
}

.side-scroller-dots ul li a span:before {
  position: absolute;
  top: -2px;
  left: -2px;
  right: -2px;
  bottom: -2px;
  content: "";
  background: #191f37;
  border-radius: 50%;
  opacity: 0;
  -webkit-transition: all .4s ease;
  transition: all .4s ease;
  z-index: -1;
}

.side-scroller-dots ul li.current a span:before {
  opacity: 1;
}

.side-scroller-dots #menu[data-section-class*='banner'] li a span,
.side-scroller-dots #menu[data-section-class*='services'] li a span,
.side-scroller-dots #menu[data-section-class*='skill'] li a span,
.side-scroller-dots #menu[data-section-class*='contact'] li a span {
  background: #191f37;
}

.side-scroller-dots #menu[data-section-class*='banner'] li.current a span,
.side-scroller-dots #menu[data-section-class*='services'] li.current a span,
.side-scroller-dots #menu[data-section-class*='skill'] li.current a span,
.side-scroller-dots #menu[data-section-class*='contact'] li.current a span {
  background: #191f37;
}




/* megamenu */

.main-menu .navigation,
.main-header .nav-outer .main-menu,
.mainmenu-nine__right,
.main-menu .navigation>.megamenu {
  position: static;
}

.main-menu .navigation>.megamenu>ul {
  top: 100% !important;
  left: 0 !important;
  right: 0 !important;
  background-color: transparent;
  box-shadow: none;
  width: 100%;
  padding: 0;
  background-color: transparent;
  border-radius: 0;
  z-index: 10;
}

.main-menu .navigation>li.megamenu-clickable>ul {
  position: fixed;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  visibility: visible;
  overflow-y: scroll;
  visibility: hidden;
  opacity: 0;
  -webkit-transform: scale(1, 0);
  transform: scale(1, 0);
  -webkit-transform-origin: bottom center;
  transform-origin: bottom center;
  transition: transform 0.7s ease;
  z-index: 999999;
  -ms-overflow-style: none;
  scrollbar-width: none;
  overflow-y: scroll;
}

.main-menu .navigation>li.megamenu-clickable>ul::-webkit-scrollbar {
  display: none;
}

.main-menu .navigation>li.megamenu-clickable>ul.megamenu-clickable--active {
  -webkit-transform-origin: top center;
  transform-origin: top center;
  -webkit-transform: scale(1, 1);
  transform: scale(1, 1);
  opacity: 1;
  visibility: visible;
  transition: transform 0.7s ease;
}

.main-menu .navigation>.megamenu>ul>li {
  padding: 0 !important;
  margin: 0;
}


.megamenu-popup-active .main-header .other-links,
.megamenu-popup-active .main-header .header-upper .logo-box {
  display: none;
}

/* Fixed Contact Note - OBTENIR UN DEVIS */
@keyframes floatUpDown {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-10px);
    }
}

.fixed-contact-note {
    position: fixed;
    bottom: 100px;
    left: 20px;
    background: linear-gradient(to right, #1915df, #440de9, #4c9cf8);
    color: var(--thm-black);
    padding: 15px 20px;
    border-radius: 50px;
    display: flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
    font-weight: 600;
    font-size: 18px;
    z-index: 999;
    padding: 15px 40px;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2);
    transition: all 300ms ease;
    font-family: var(--thm-font);
    animation: floatUpDown 1.2s ease-in-out infinite;
}

.fixed-contact-note:hover {
    background: var(--thm-black);
    color: #ffffff;
    transform: translateY(-13px);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.3);
    animation-play-state: paused;
}

.fixed-contact-note i {
    font-size: 18px;
}

.fixed-contact-note span {
    white-space: nowrap;
}

@media (max-width: 768px) {
    .fixed-contact-note {
        bottom: 80px;
        left: 10px;
        padding: 12px 16px;
        font-size: 14px;
    }

    .fixed-contact-note span {
        display: none;
    }

    .fixed-contact-note i {
        font-size: 20px;
    }
}
